"""Deterministic synthetic screen for task-specific Hebbian plasticity coefficients."""
import argparse, json, time
from pathlib import Path
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
D=12; TASKS=8; RANK=2; N_SUPPORT=24; N_QUERY=128

def make(seed):
    rng=np.random.default_rng(seed)
    # Shared basis tensors and aligned task codes; teacher maps are generated by the same
    # modulation family, so this is deliberately favorable to coefficient sharing.
    basis=rng.normal(size=(RANK,D,D))/np.sqrt(D)
    z=rng.normal(size=(TASKS,RANK))
    plastic=np.einsum('tr,rij->tij',z,basis)
    # Set a stable shared slow predictor; task-specific residual map is learned by fast writes.
    teachers=plastic.copy()
    support=[]; query=[]
    for t in range(TASKS):
        xs=rng.normal(size=(N_SUPPORT+N_QUERY,D))/np.sqrt(D)
        ys=xs@teachers[t].T
        support.append((xs[:N_SUPPORT],ys[:N_SUPPORT])); query.append((xs[N_SUPPORT:],ys[N_SUPPORT:]))
    return basis,z,plastic,teachers,support,query

def eval_rule(seed, rank=None, independent=False, common=False):
    basis,z,plastic,teachers,support,query=make(seed)
    if common: mods=np.broadcast_to(plastic.mean(0),(TASKS,D,D)).copy()
    elif independent: mods=plastic.copy()
    else:
        # Fit a rank-r table in task coefficient space; native factor and Mirror are same state.
        u,s,v=np.linalg.svd(z,full_matrices=False); rr=RANK if rank is None else rank
        zhat=(u[:,:rr]*s[:rr])@v[:rr]
        mods=np.einsum('tr,rij->tij',zhat,basis)
    errs=[]; update_macs=0; state_bytes=0
    for t,(sx,sy) in enumerate(support):
        fast=np.zeros((D,D),dtype=np.float64)
        for x,y in zip(sx,sy):
            # Hebbian outer-product write, modulated by the task's plasticity tensor.
            fast += D*np.outer(y,x)*mods[t]/len(sx)
        qx,qy=query[t]; pred=qx@fast.T
        errs.append(np.mean((pred-qy)**2)/(np.mean(qy*qy)+1e-12))
        update_macs+=len(sx)*D*D*D
        state_bytes+=fast.astype('<f4').nbytes
    # Actual inference payload: arrays in deterministic NPZ plus JSON header.
    if independent: arrays={'plasticity':plastic.astype('<f4')}
    elif common: arrays={'plasticity':mods[:1].astype('<f4')}
    else: arrays={'basis':basis.astype('<f4'),'codes':z.astype('<f4') if rank is None or rank==RANK else ((np.linalg.svd(z,full_matrices=False)[0][:,:rank]*np.linalg.svd(z,full_matrices=False)[1][:rank])@np.linalg.svd(z,full_matrices=False)[2][:rank]).astype('<f4')}
    p=ROOT/'source'/'_payload.npz'; np.savez(p,**arrays)
    payload=p.stat().st_size+len(json.dumps({'d':D,'tasks':TASKS,'rank':rank,'method':'synthetic'}).encode())
    p.unlink()
    return float(np.mean(errs)),payload,state_bytes,update_macs

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--development',action='store_true'); ap.add_argument('--fresh',action='store_true'); args=ap.parse_args()
    seeds=[11] if args.development else ([29,47] if args.fresh else [11,29,47])
    methods=[('common',dict(common=True)),('independent_coefficients',dict(independent=True)),('native_low_rank',dict(rank=RANK)),('mirror_code_bank',dict(rank=RANK)),('independent_full_tensor',dict(independent=True))]
    out=[]
    for seed in seeds:
        for name,kw in methods:
            t=time.perf_counter(); e,b,s,m=eval_rule(seed,**kw); wall=time.perf_counter()-t
            out.append(dict(seed=seed,method=name,query_nrmse=float(np.sqrt(e)),persistent_payload_bytes=b,writable_fast_state_bytes=s,total_bytes=b+s,examples=TASKS*N_SUPPORT,optimizer_updates=0,hebbian_update_macs=m,wall_time_s=wall))
    print(json.dumps(out,indent=2))
if __name__=='__main__': main()
